import SwiftUI
import AppKit

struct AIProviderBrandIcon: View {
    let provider: String
    var size: CGFloat = 20
    var isSelected: Bool = false
    
    var body: some View {
        if let nsImage = Self.image(for: provider) {
            Image(nsImage: nsImage)
                .resizable()
                .interpolation(.high)
                .aspectRatio(contentMode: .fit)
                .frame(width: size, height: size)
        } else if let microcodeImg = Self.image(for: "microcode") {
            Image(nsImage: microcodeImg)
                .resizable()
                .interpolation(.high)
                .aspectRatio(contentMode: .fit)
                .frame(width: size, height: size)
        }
    }
    
    private static var iconCache: [String: NSImage] = [:]
    private static var menuIconCache: [String: NSImage] = [:]
    
    static func resolveKey(for provider: String) -> String {
        let rawKey = provider
            .lowercased()
            .trimmingCharacters(in: .whitespacesAndNewlines)
            .replacingOccurrences(of: "-", with: "_")
            .replacingOccurrences(of: " ", with: "_")
        switch rawKey {
        case "agy", "antigravity", "google_antigravity":
            return "agy"
        case "claude", "claudecode", "claude_code":
            return "claude"
        case "anthropic":
            return "anthropic"
        case "openai", "chatgpt":
            return "openai"
        case "codex", "codexengine", "codex_engine":
            return "codex"
        case "gemini", "google", "google_gemini":
            return "gemini"
        case "gemini_cli", "geminicli":
            return "gemini_cli"
        case "opencode", "open_code":
            return "opencode"
        case "cursor", "cursoragent", "cursor_agent":
            return "cursor"
        case "copilot", "githubcopilot", "github_copilot", "github":
            return "copilot"
        case "goose", "block_goose":
            return "goose"
        case "cline", "cline_cli":
            return "cline"
        case "roo", "roocode", "roo_code":
            return "roo"
        case "windsurf":
            return "windsurf"
        case "amp", "sourcegraph_amp":
            return "amp"
        case "aider":
            return "aider"
        case "zed", "zedengine", "zed_engine", "zcode":
            return "zed"
        case "9router", "ninerouter", "9_router":
            return "9router"
        case "openrouter", "open_router":
            return "openrouter"
        case "litellm", "lite_llm":
            return "litellm"
        case "deepseek", "deep_seek":
            return "deepseek"
        case "qwen", "qwencode", "qwen_code", "dashscope":
            return "qwen"
        case "glm", "zhipu", "chatglm", "zai", "z_ai":
            return "glm"
        case "grok", "xai", "x_ai":
            return "grok"
        case "groq":
            return "groq"
        case "mistral", "codestral", "devstral":
            return "mistral"
        case "kimi", "moonshot":
            return "kimi"
        case "perplexity", "sonar":
            return "perplexity"
        case "typhoon", "opentyphoon", "scb10x":
            return "typhoon"
        case "cerebras":
            return "cerebras"
        case "together", "together_ai":
            return "together"
        case "fireworks", "fireworks_ai":
            return "fireworks"
        case "minimax":
            return "minimax"
        case "nvidia", "nvidia_nim", "nim":
            return "nvidia"
        case "local", "ollama", "free_model", "freemodel":
            return "local"
        case "lmstudio", "lm_studio":
            return "lmstudio"
        case "vllm", "mlx":
            return "vllm"
        case "aipass", "thai_passport", "th_ai_pass":
            return "aipass"
        case "microcode", "microcodenative", "microcode_native", "omni", "dotmini", "custom":
            return "microcode"
        default:
            if base64Data[rawKey] != nil {
                return rawKey
            }
            if rawKey.contains("9router") { return "9router" }
            if rawKey.contains("openrouter") { return "openrouter" }
            if rawKey.contains("claude") { return "claude" }
            if rawKey.contains("anthropic") { return "anthropic" }
            if rawKey.contains("gemini_cli") { return "gemini_cli" }
            if rawKey.contains("gemini") { return "gemini" }
            if rawKey.contains("agy") || rawKey.contains("antigravity") { return "agy" }
            if rawKey.contains("codex") { return "codex" }
            if rawKey.contains("openai") || rawKey.contains("gpt") { return "openai" }
            if rawKey.contains("cursor") { return "cursor" }
            if rawKey.contains("copilot") || rawKey.contains("github") { return "copilot" }
            if rawKey.contains("goose") { return "goose" }
            if rawKey.contains("cline") { return "cline" }
            if rawKey.contains("roo") { return "roo" }
            if rawKey.contains("qwen") { return "qwen" }
            if rawKey.contains("deepseek") { return "deepseek" }
            if rawKey.contains("glm") || rawKey.contains("zhipu") { return "glm" }
            if rawKey.contains("grok") || rawKey.contains("xai") { return "grok" }
            if rawKey.contains("groq") { return "groq" }
            if rawKey.contains("mistral") { return "mistral" }
            if rawKey.contains("kimi") || rawKey.contains("moonshot") { return "kimi" }
            if rawKey.contains("lmstudio") || rawKey.contains("lm_studio") { return "lmstudio" }
            if rawKey.contains("ollama") || rawKey.contains("local") { return "local" }
            return "microcode"
        }
    }
    
    static func image(for provider: String) -> NSImage? {
        let resolvedKey = resolveKey(for: provider)
        if let cached = iconCache[resolvedKey] {
            return cached
        }
        guard let base64 = base64Data[resolvedKey],
              let data = Data(base64Encoded: base64),
              let img = NSImage(data: data) else {
            return nil
        }
        iconCache[resolvedKey] = img
        return img
    }
    
    /// Returns a sized NSImage suitable for AppKit NSMenuItem.image
    static func menuImage(for provider: String, size: CGFloat = 15) -> NSImage? {
        let resolvedKey = resolveKey(for: provider)
        let cacheKey = "\(resolvedKey)_\(Int(size))"
        if let cached = menuIconCache[cacheKey] {
            return cached
        }
        guard let baseImg = image(for: resolvedKey),
              let copy = baseImg.copy() as? NSImage else {
            return nil
        }
        copy.size = NSSize(width: size, height: size)
        menuIconCache[cacheKey] = copy
        return copy
    }
    
    private static let base64Data: [String: String] = [
        "9router": "",
        "agy": "",
        "aider": "",
        "aipass": "",
        "amp": "",
        "anthropic": "",
        "cerebras": "",
        "claude": "",
        "cline": "",
        "codex": "",
        "copilot": "",
        "cursor": "",
        "deepseek": "",
        "fireworks": "",
        "gemini": "",
        "gemini_cli": "",
        "glm": "",
        "goose": "",
        "grok": "",
        "groq": "",
        "kimi": "",
        "litellm": "",
        "lmstudio": "",
        "local": "",
        "microcode": "",
        "minimax": "",
        "mistral": "",
        "nvidia": "",
        "openai": "",
        "opencode": "",
        "openrouter": "",
        "perplexity": "",
        "qwen": "",
        "roo": "",
        "together": "",
        "typhoon": "",
        "vllm": "",
        "windsurf": "",
        "zed": "",
    ]
}


// MARK: - Authentic Programming Language & File-Type Icon View

public struct ProgrammingLanguageIconView: View {
    public let fileName: String
    public var languageHint: String = ""
    public var size: CGFloat = 15
    
    public init(fileName: String, languageHint: String = "", size: CGFloat = 15) {
        self.fileName = fileName
        self.languageHint = languageHint
        self.size = size
    }
    
    private var resolvedKey: String {
        let lowerFile = URL(fileURLWithPath: fileName).lastPathComponent.lowercased()
        let ext = URL(fileURLWithPath: lowerFile).pathExtension.lowercased()
        if lowerFile == "dockerfile" || lowerFile.hasPrefix("dockerfile.") || lowerFile == "docker-compose.yml" || lowerFile == "docker-compose.yaml" {
            return "docker"
        }
        if lowerFile == "cargo.toml" || lowerFile == "cargo.lock" {
            return "rs"
        }
        if lowerFile == "package.json" || lowerFile == "package-lock.json" {
            return "npm"
        }
        if lowerFile == "go.mod" || lowerFile == "go.sum" {
            return "go"
        }
        if lowerFile.hasPrefix(".git") {
            return "git"
        }
        if !ext.isEmpty {
            return ext
        }
        return languageHint.lowercased().trimmingCharacters(in: .whitespacesAndNewlines)
    }
    
    public var body: some View {
        if let themeIcon = ExtensionManager.shared.iconImage(for: URL(fileURLWithPath: fileName).lastPathComponent, isDirectory: false, isExpanded: false) {
            Image(nsImage: themeIcon)
                .resizable()
                .interpolation(.high)
                .aspectRatio(contentMode: .fit)
                .frame(width: size, height: size)
        } else {
            authenticVectorBadge
                .frame(width: size, height: size)
        }
    }
    
